import js from '@eslint/js'
import astro from 'eslint-plugin-astro'
import ts from 'typescript-eslint'

// ponytail: typescript is pinned to ^6.0.3 in package.json because typescript-eslint
// does not support TS 7 yet (peer: >=4.8.4 <6.1.0). Move to TS 7 once it does, or drop
// typescript-eslint and rely on `astro check` + TS strict alone.

export default [
  // `.claude/worktrees/*` holds throwaway agent worktrees, each with its own
  // tsconfig.json. Left visible, typescript-eslint sees several candidate roots and
  // refuses to parse anything.
  {
    ignores: [
      'dist/',
      '.astro/',
      'node_modules/',
      'handoff/',
      '.claude/',
      'test-results/',
      'playwright-report/',
      '.lighthouseci/',
    ],
  },
  js.configs.recommended,
  ...ts.configs.recommended,
  ...astro.configs.recommended,
]

import { expect, test } from 'bun:test'

const root = new URL('../', import.meta.url)
const astroConfig = await Bun.file(new URL('astro.config.mjs', root)).text()
const pkg = await Bun.file(new URL('package.json', root)).json()

test('astro.config.mjs declares static output', () => {
  expect(astroConfig).toMatch(/output:\s*['"]static['"]/)
})

test('package.json exposes every script the workflow depends on', () => {
  const scripts = ['dev', 'build', 'preview', 'lint', 'format', 'test', 'test:e2e', 'test:lh']
  expect(Object.keys(pkg.scripts as Record<string, string>).sort()).toEqual(scripts.sort())
})
